      links: [['Network Policies', 'https://kubernetes.io/docs/concepts/services-networking/network-policies/'], ['Ingress TLS', 'https://kubernetes.io/docs/concepts/services-networking/ingress/#tls'], ['cert-manager', 'https://cert-manager.io/docs/'], ['Istio Security', 'https://istio.io/latest/docs/concepts/security/']],
